args.sql:
ALTER TABLE cases ADD COLUMN complexity INTEGER;

UPDATE cases SET complexity = (
  CASE WHEN h1bdep = 'Yes' THEN 1 ELSE 0 END +
  CASE WHEN willfulv = 'Yes' THEN 1 ELSE 0 END +
  CASE WHEN newemp > 0 THEN 1 ELSE 0 END +
  CASE WHEN amendflag > 0 THEN 1 ELSE 0 END
);

